//! Metadata compatibility only; never creates an actual registered/Root owner.
use super::*;
#[test]
fn image_batch_v2_metadata_has_exact_existing_fields_and_image_budget_class(){let op=EngineOperationKind::BeginImagePreseedV2{workspace_id:"fixture".into(),manifest:ObjectRef::from_bytes(ObjectKind::Blob,b"manifest"),installer_input:ObjectRef::from_bytes(ObjectKind::Directory,b"directory"),image_receipt_sha256:"a".repeat(64)};op.validate().unwrap();assert!(op.image()&&op.begin_upload());let v=serde_json::to_value(&op).unwrap();assert_eq!(v["op"],"BeginImagePreseedV2");assert_eq!(v.as_object().unwrap().len(),5);assert!(serde_json::from_value::<EngineOperationKind>(serde_json::json!({"op":"BeginImagePreseedV2","workspace_id":"fixture","retained":true})).is_err());}
#[test]
fn image_batch_v2_retains_exact_warm_reuse_discriminator(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../tests/fixtures/engine_registration/hmac-vectors.json")).unwrap();let mut a:EngineOperationAck=serde_json::from_value(fixture["vectors"].as_array().unwrap().iter().find(|v|v["phase"]=="operation_ack").unwrap()["body"].clone()).unwrap();a.operation=EngineOperationKind::BeginImagePreseedV2{workspace_id:"fixture".into(),manifest:ObjectRef::from_bytes(ObjectKind::Blob,b"manifest"),installer_input:ObjectRef::from_bytes(ObjectKind::Directory,b"directory"),image_receipt_sha256:"a".repeat(64)};a.result=Some(serde_json::json!({"scope":"image-preseed-reuse-only"}));assert!(has_image_reuse_result(&a));a.operation=EngineOperationKind::PrepareFreshProjectV1{workspace_id:"fixture".into()};assert!(!has_image_reuse_result(&a));}
